const report = $('Przygotuj zgloszenie1').first().json;
let cameras = $input.first().json.cameras;

if (typeof cameras === 'string') cameras = JSON.parse(cameras);
if (!Array.isArray(cameras)) {
  throw new Error('Nieprawidłowa lista kamer');
}

function normalize(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/ł/g, 'l')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\b(?:ulica|ulicy|ulice|ul)\b\.?/g, ' ')
    .replace(/\b(?:wawelem|wawelu)\b/g, 'wawel')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ');
}

function containsPhrase(text, phrase) {
  return (` ${text} `).includes(` ${phrase} `);
}

const address = normalize(report.address);
const generic = new Set([
  'kamera', 'centrum', 'krakow', 'kielce', 'ulica', 'plac'
]);

const candidates = cameras.flatMap(camera => {
  // Pełna nazwa oraz człony, np. "Wawel" i "Zamek Królewski".
  const keys = [
    normalize(camera.name),
    ...String(camera.name ?? '').split(/[·|;—]/).map(normalize)
  ].filter(key => key.length >= 4 && !generic.has(key));

  const matches = keys.filter(key => containsPhrase(address, key));
  if (!matches.length) return [];

  const lon = Number(camera.longitude);
  const lat = Number(camera.latitude);

  if (
    camera.longitude == null || camera.latitude == null ||
    !Number.isFinite(lon) || !Number.isFinite(lat) ||
    Math.abs(lon) > 180 || Math.abs(lat) > 90
  ) return [];

  return [{
    camera,
    score: Math.max(...matches.map(key => key.length))
  }];
});

candidates.sort((a, b) =>
  b.score - a.score ||
  String(a.camera.id).localeCompare(String(b.camera.id))
);

// Nie wybieraj przypadkowej kamery przy równorzędnych wynikach.
const ambiguous =
  candidates.length > 1 &&
  candidates[0].score === candidates[1].score;

const camera = !ambiguous ? candidates[0]?.camera : null;

return [{
  json: {
    ...report,
    description:
      report.description + '\nAdres zgłoszenia: ' + report.address,
    longitude: camera ? Number(camera.longitude) : report.longitude,
    latitude: camera ? Number(camera.latitude) : report.latitude,
    camera_id: camera?.id ?? null,
    camera_match: ambiguous
      ? 'ambiguous'
      : camera ? 'matched' : 'not_found',
    matched_camera_name: camera?.name ?? null,
    matched_camera_count: candidates.length
  }
}];

const data = $input.first().json.body;
if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error('Oczekiwano obiektu JSON w body webhooka');
const categories = ['drogi','zielen','woda','odpady','oswietlenie','dostepnosc','bezpieczenstwo','inne'];
function text(value, field) {
  if (typeof value !== 'string' || !value.trim()) throw new Error('Brak pola: ' + field);
  return value.trim();
}
function coordinate(value, min, max, field) {
  if (value === undefined || value === null || value === '') return null;
  if (!['number','string'].includes(typeof value) || String(value).trim() === '') throw new Error('Nieprawidlowe pole: ' + field);
  const n = Number(value);
  if (!Number.isFinite(n) || n < min || n > max) throw new Error('Nieprawidlowa wspolrzedna: ' + field);
  return n;
}
const longitude = coordinate(data.longitude, -180, 180, 'longitude');
const latitude = coordinate(data.latitude, -90, 90, 'latitude');
if ((longitude === null) !== (latitude === null)) throw new Error('Przeslij obie wspolrzedne albo zadnej');
let blocking = false;
if (data.blocking === true || data.blocking === 'true') blocking = true;
else if (data.blocking === false || data.blocking === 'false') blocking = false;
else if (data.blocking != null && data.blocking !== '') throw new Error('blocking musi byc true lub false');
return [{json: {
  address: text(data.address ?? data.adres ?? data.street ?? data.ulica, 'address'),
  title: text(data.title, 'title'),
  description: text(data.description, 'description'),
  category: categories.includes(data.category) ? data.category : 'inne',
  longitude, latitude, blocking
}}];
